from itertools import combinations
feats={'1':np.ones_like(P),'P':P,'P2':P**2,'P3':P**3,'t':t,'t2':t**2,'tP':t*P,'t2P':t**2*P,'tP2':t*P**2,'lnP':np.log(P),'1/P':1/P,'P_lnP':P*np.log(P),'sqrtP':np.sqrt(P)}
names=list(feats)
best=[]
for k in range(2,6):
    for comb in combinations(names,k):
        if '1' not in comb: continue
        X=np.c_[[feats[c] for c in comb]].T
        c,_,_,_=np.linalg.lstsq(X,dP_dt,rcond=None)
        r=np.mean((X@c-dP_dt)**2)/np.var(dP_dt)
        best.append((r,comb,np.round(c,4)))
best.sort(key=lambda x:x[0])
for b in best[:8]: print(b)

